CREATE DATABASE IF NOT EXISTS qris_subscription CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE qris_subscription;
CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE customers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, whatsapp VARCHAR(30) NOT NULL, username VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, status ENUM('active','suspended') NOT NULL DEFAULT 'active', subscription_start DATETIME NULL, subscription_expiry DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(subscription_expiry)) ENGINE=InnoDB;
CREATE TABLE subscription_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, customer_id BIGINT UNSIGNED NOT NULL, action ENUM('activate','extend','suspend','unsuspend') NOT NULL, days INT NOT NULL DEFAULT 30, old_expiry DATETIME NULL, new_expiry DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE) ENGINE=InnoDB;
